import type { MetadataRoute } from "next";

/**
 * Single source of truth for the PWA manifest (served at /manifest.webmanifest
 * by the App Router metadata convention - no `manifest` field belongs in
 * layout.tsx). Icons are generated by `npm run icons`
 * (scripts/generate-icons.cjs) from public/logo.png into public/.
 *
 * Colors for the installed-app launch:
 *   theme_color / background_color  #000000 - drives the black splash screen
 *                    (background_color paints behind the first frame) and the
 *                    black launcher backdrop; the in-app 1.5s splash overlay
 *                    lives in src/components/app-splash.tsx + globals.css.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "NetGuard — Digital Footprint & Social Media Safety",
    short_name: "NetGuard",
    description: "Social Media Safety and Digital Footprint Awareness",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    theme_color: "#000000",
    background_color: "#000000",
    icons: [
      {
        src: "/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      // Maskable is its own entry - never "any maskable" combined, the
      // safe-zone padding rules are different for the two purposes.
      {
        src: "/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
